doc = Document()
doc.add_heading('Іс-тәжірибе күнделігіне арналған Қауіпсіздік техникасы (Техника безопасности)', level=1)

for date, text in text_data:
    p = doc.add_paragraph()
    r_date = p.add_run(f"{date} - ")
    r_date.bold = True
    r_text = p.add_run(text)
    
doc.save('Практика_Қауіпсіздік_Ережелері.docx')
